def date(s):
 m=re.search(r'(\d{1,2})\.\s+([A-Za-zä]+)\s+(\d{4})',str(s))
 return pd.Timestamp(year=int(m[3]),month=months[m[2]],day=int(m[1])) if m and m[2] in months else pd.NaT
t['coupon_verified']=pd.to_numeric(t.title.str.extract(r'([0-9]+[.,][0-9]+)\s*%')[0].str.replace(',','.'),errors='coerce');t['start_verified']=t.accrual_start.map(date);t['first_verified']=t.first_coupon.map(date);t['maturity_verified']=pd.to_datetime(t.maturity,format='%d.%m.%Y',errors='coerce');t['inflation_linked']=t.title.fillna('').str.contains('inflation',case=False)
