d=pd.read_parquet(p/'official_all.parquet');s=d.merge(t[['isin','coupon_verified','start_verified','first_verified','maturity_verified','inflation_linked','url']],on='isin',validate='many_to_one');changes=s[~np.isclose(s.coupon,s.coupon_verified)];changes.groupby('isin').agg(rows=('date','size'),raw_coupon=('coupon','first'),verified_coupon=('coupon_verified','first'),url=('url','first')).to_csv(p/'coupon_corrections.csv');s['coupon_raw']=s.coupon;s['coupon']=s.coupon_verified;s['maturity_raw']=s.maturity;s['maturity']=s.maturity_verified;s.to_parquet(p/'official_all_verified.parquet',index=False)
q=pd.read_parquet(p/'official_twins.parquet');pairs=q[['isin_g','isin_c']].drop_duplicates().rename(columns={'isin_g':'gid','isin_c':'cid'});g=s.merge(pairs,left_on='isin',right_on='gid');v=g.merge(s,left_on=['cid','date'],right_on=['isin','date'],suffixes=('_g','_c'));v=v[(v.coupon_g==v.coupon_c)&(v.maturity_g==v.maturity_c)].copy();v['gap_bp']=100*(v.yield_pct_g-v.yield_pct_c);v['coupon']=v.coupon_g;v['maturity']=v.maturity_g;v=v[v.gap_bp.notna()&(v.date<v.maturity)];v.to_parquet(p/'official_twins_verified.parquet',index=False)
r={'raw_isins':d['isin'].nunique(),'verified_isins':t['isin'].nunique(),'excluded_isins':sorted(set(d['isin'])-set(t['isin'])),'coupon_changed_rows':len(changes),'coupon_changed_isins':changes['isin'].nunique(),'maturity_changed_rows':int((s.maturity_raw!=s.maturity_verified).sum()),'verified_twin_rows':len(v)};(p/'term_repair_audit.json').write_text(json.dumps(r,indent=2));print(json.dumps(r,indent=2))
